// Generated by velora init. Recipe imports belong in this React refresh boundary.
import { ProjectPreview } from "@adityadeokar/velora/preview";
import type { ComponentProps } from "react";

const sceneModules = import.meta.env.DEV ? import.meta.glob("/src/velora/scenes/*.{scene.json,tsx,jsx}") : undefined;
const compositionModules = import.meta.env.DEV ? import.meta.glob("/*.composition.json") : undefined;
const assetUrls = import.meta.env.DEV ? import.meta.glob("/**/*.{mp3,wav,m4a,aac,ogg,opus,flac,srt,vtt}", { query: "?url", import: "default", eager: true }) : undefined;

export function VeloraProjectPreview(props: Omit<ComponentProps<typeof ProjectPreview>, "sceneModules" | "hot" | "compositionModules" | "assetUrls">) {
  if (!import.meta.env.DEV) return props.children;
  return <ProjectPreview {...props} sceneModules={sceneModules} compositionModules={compositionModules} assetUrls={assetUrls as Record<string, string> | undefined} hot={import.meta.hot} />;
}
